'use strict';
// Entirely synthetic fixtures. No requests, storage, real accounts or real payments.
const members=[
{id:1,name:'Demo člen Alfa',email:'alfa@example.invalid',phone:'+420 000 000 001',status:'Aktivní',due:5000,paid:5000},
{id:2,name:'Demo člen Beta',email:'beta@example.invalid',phone:'+420 000 000 002',status:'Aktivní',due:5000,paid:0},
{id:3,name:'Demo člen Gama',email:'gama@example.invalid',phone:'+420 000 000 003',status:'Aktivní',due:5000,paid:2500},
{id:4,name:'Demo člen Delta',email:'delta@example.invalid',phone:'+420 000 000 004',status:'Aktivní',due:5000,paid:5000},
{id:5,name:'Demo člen Epsilon',email:'epsilon@example.invalid',phone:'+420 000 000 005',status:'Ukončené',due:0,paid:0}];
let page='overview';const $=s=>document.querySelector(s);const money=n=>new Intl.NumberFormat('cs-CZ',{style:'currency',currency:'CZK',maximumFractionDigits:0}).format(n);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const debt=m=>Math.max(0,m.due-m.paid);const state=m=>m.due===0?'Bez předpisu':debt(m)===0?'Uhrazeno':m.paid?'Částečně':'Neuhrazeno';const badge=m=>`<span class="badge ${debt(m)?'warn':m.due?'':'gray'}">${state(m)}</span>`;
const titles={overview:'Dobrý den, sekretariáte',members:'Členská evidence',payments:'Členské příspěvky',forum:'Diskuse a rozhodnutí'};
function render(){ $('#title').textContent=titles[page];document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(page==='members')renderMembers();if(page==='overview')renderOverview();if(page==='payments')renderPayments();if(page==='forum')renderForum();}
function renderOverview(){const active=members.filter(m=>m.status==='Aktivní');$('#content').innerHTML=`<div class="stats"><div class="stat">Aktivní členové<strong>${active.length}</strong><small>Ukázková evidence</small></div><div class="stat">Přijato za rok 2026<strong>${money(members.reduce((n,m)=>n+m.paid,0))}</strong><small>Fiktivní ruční úhrady</small></div><div class="stat">Zbývá uhradit<strong>${money(members.reduce((n,m)=>n+debt(m),0))}</strong><small>${members.filter(m=>debt(m)).length} neuhrazené předpisy</small></div></div><div class="grid"><section class="panel"><h2>Vyžaduje pozornost</h2>${members.filter(m=>debt(m)).map(m=>`<div class="row"><div><button class="name" data-member="${m.id}">${esc(m.name)}</button><div class="sub">${state(m)}</div></div><strong>${money(debt(m))}</strong></div>`).join('')}<p class="sub">Urgence ani platby se z prototypu neodesílají.</p></section><section class="panel"><h2>Napojení banky</h2><span class="badge gray">Fio není připojeno</span><p>V produkční verzi se zde zobrazí poslední synchronizace a platby k ruční kontrole.</p><button data-go="payments">Přejít na příspěvky →</button></section></div><section class="panel"><h2>Pracovní prostor</h2><p>Členové, příspěvky a rozhodnutí na jednom místě.</p><button data-go="forum">Otevřít diskusi →</button></section>`;}
function renderMembers(){ $('#content').innerHTML=`<section class="panel"><div class="tools"><input id="search" type="search" aria-label="Vyhledat člena" placeholder="Hledat jméno nebo e-mail…"><select id="filter" aria-label="Stav členství"><option>Všichni</option><option>Aktivní</option><option>Ukončené</option><option>S nedoplatkem</option></select></div><div class="tablewrap"><table><thead><tr><th>Člen</th><th>Kontakt</th><th>Členství</th><th>Příspěvek 2026</th></tr></thead><tbody id="rows"></tbody></table></div><p id="count" class="sub"></p></section>`;$('#search').addEventListener('input',filterMembers);$('#filter').addEventListener('change',filterMembers);filterMembers();}
function filterMembers(){const q=$('#search').value.toLocaleLowerCase('cs');const f=$('#filter').value;const list=members.filter(m=>(m.name+' '+m.email).toLocaleLowerCase('cs').includes(q)&&(f==='Všichni'||(f==='S nedoplatkem'?debt(m)>0:m.status===f)));$('#rows').innerHTML=list.map(m=>`<tr><td><button class="name" data-member="${m.id}">${esc(m.name)}</button><div class="sub">DEMO-${String(m.id).padStart(3,'0')}</div></td><td>${esc(m.email)}</td><td>${esc(m.status)}</td><td>${badge(m)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">Žádný člen neodpovídá hledání.</td></tr>';$('#count').textContent=`Zobrazeno ${list.length} z ${members.length} ukázkových členů`;}
function openMember(id){const m=members.find(m=>m.id===id);$('#detail').innerHTML=`<p class="eyebrow">ČLENSKÁ KARTA / DEMO-${m.id}</p><h2>${esc(m.name)}</h2><span class="badge gray">${esc(m.status)}</span><form id="contact"><label>E-mail<input name="email" type="email" required value="${esc(m.email)}"></label><label>Telefon<input name="phone" type="tel" value="${esc(m.phone)}"></label><button class="primary">Vyzkoušet uložení kontaktu</button></form><p id="feedback" class="message" role="status"></p><hr><h3>Příspěvek 2026</h3><p>Předpis ${money(m.due)} · přijato ${money(m.paid)}</p>${badge(m)}<p class="sub">Historická evidence se v ostré verzi zobrazí odděleně od bankovních transakcí.</p>${m.status==='Aktivní'?`<details><summary>Připravit ukončení členství</summary><p class="sub">Pouze ukázka návrhu. Členství se zde neukončí.</p><form id="end"><label>Důvod návrhu<textarea required name="reason"></textarea></label><button>Vyzkoušet návrh</button></form><p id="endmsg" class="message" role="status"></p></details>`:''}`;$('#contact').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);m.email=String(data.get('email')).trim();m.phone=String(data.get('phone')).trim();$('#feedback').textContent='Kontakt změněn pouze v paměti této ukázky.';render();};if($('#end'))$('#end').onsubmit=e=>{e.preventDefault();$('#endmsg').textContent='Ukázkový návrh připraven. V produkci se připojí datum a schválené rozhodnutí.';};$('#card').showModal();}
function renderPayments(){ $('#content').innerHTML=`<section class="panel"><div class="row"><h2>Předpisy pro rok 2026</h2><span class="pill">Ukázková sazba 5 000 Kč</span></div><div class="tablewrap"><table><thead><tr><th>Člen</th><th>Předpis</th><th>Uhrazeno</th><th>Zbývá</th><th>Stav</th></tr></thead><tbody>${members.map(m=>`<tr><td><button class="name" data-member="${m.id}">${esc(m.name)}</button></td><td>${money(m.due)}</td><td>${money(m.paid)}</td><td>${money(debt(m))}</td><td>${badge(m)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>Platby k posouzení</h2><span class="badge gray">Bankovní napojení čeká na implementaci</span><p>Sem budou patřit chybějící variabilní symboly, částečné platby a převody za více členů. Žádný údaj z této ukázky nepochází z banky.</p></section>`;}
const replies=[];
function renderForum(){ $('#content').innerHTML=`<section class="panel"><p class="eyebrow">SPOLEČNÁ SEKCE · UKÁZKA</p><h2>Jak budeme pracovat s členskou evidencí?</h2><p class="muted">Ukázkové téma · Sekretariát</p><div class="post">Navrhujeme nejdříve ověřit seznam členů a jejich karty, potom přidat automatické párování plateb.</div>${replies.map(r=>`<div class="post"><strong>Ukázkový účet</strong><p>${esc(r)}</p></div>`).join('')}<form id="reply"><label>Vyzkoušet odpověď<textarea name="body" required maxlength="2000" placeholder="Text zůstane jen v této ukázce…"></textarea></label><button class="primary">Přidat ukázkovou odpověď</button></form></section><section class="panel"><h2>Oddělení sekcí v produkci</h2><p>Výbor · Revizní komise · Společná agenda</p><p class="sub">Přístupy bude ověřovat server. Tento prototyp přihlášení ani ochranu sekcí neobsahuje.</p></section>`;$('#reply').onsubmit=e=>{e.preventDefault();const body=String(new FormData(e.target).get('body')).trim();if(body){replies.push(body);renderForum();}};}
document.addEventListener('click',e=>{const member=e.target.closest('[data-member]');const go=e.target.closest('[data-go]');const nav=e.target.closest('[data-page]');if(member)openMember(Number(member.dataset.member));if(go||nav){page=go?go.dataset.go:nav.dataset.page;render();}});$('.close').onclick=()=>$('#card').close();render();
